@push('scripts')<script>document.getElementById('sellerFiles')?.addEventListener('change',async e=>{const box=document.getElementById('uploadIds'),status=document.getElementById('uploadStatus');box.innerHTML='';status.textContent='در حال بارگذاری...';for(const file of e.target.files){const fd=new FormData();fd.append('file',file);try{const r=await fetch('{{ route('seller.products.uploads.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:fd});const j=await r.json();if(!r.ok)throw new Error(j.message||'خطا');(j.files||[]).forEach(f=>{const input=document.createElement('input');input.type='hidden';input.name='upload_ids[]';input.value=f.id;box.appendChild(input);});status.textContent='فایل‌های آماده ارسال: '+box.querySelectorAll('input').length;}catch(err){status.textContent='خطا: '+err.message;}}});</script>@endpush